// A trailing slash must not hide a symlink from lstat.
const rootName = typeof root === 'string' ? root.replace(/\/+$/, '') || '/' : root;
const stat = fs.lstatSync(rootName);

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)
    || manifest.version !== 1 || !Array.isArray(manifest.files)) throw Error('invalid manifest');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('invalid manifest entry');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)
      || !Number.isSafeInteger(entry.size) || entry.size < 0
      || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid manifest metadata');
  }
}

export function verifyManifest(root, manifest) {
  validateManifest(manifest);
  validateRoot(root);
  const report = {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]};
  const entries = [...manifest.files].sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
  for (const entry of entries) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing' || current.kind === 'unsafe') {
      report[current.kind].push(entry.path);
      continue;
    }
    const reasons = [];
    if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
    if (current.mode !== entry.mode) reasons.push('mode');
    if (reasons.length) report.changed.push({path:entry.path, reasons});
    else report.unchanged.push(entry.path);
  }
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(args) {
  try {
    const [command, root, ...rest] = args;
    let result;
    let status = 0;
    if (command === 'create' && args.length >= 2) {
      result = createManifest(root, rest);
    } else if (command === 'verify' && args.length === 3) {
      const manifest = JSON.parse(fs.readFileSync(rest[0], 'utf8'));
      result = verifyManifest(root, manifest);
      status = result.ok ? 0 : 1;
    } else {
      throw Error('usage: snapshot.js create ROOT [PATH ...] | verify ROOT MANIFEST_FILE');
    }
    process.stdout.write(JSON.stringify(result) + '\n');
    process.exitCode = status;
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  runCli(process.argv.slice(2));
}

