import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, { recursive:true, force:true }));
  return root;
}
function put(root, name, bytes = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), { recursive:true });
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
function cli(args) {
  const result = spawnSync(process.execPath, [script, ...args], { encoding:'utf8' });
  assert.ifError(result.error);
  assert.equal(result.signal, null);
  return result;
}
function success(args, status, expected) {
  const result = cli(args);
  assert.equal(result.status, status);
  assert.equal(result.stderr, '');
  assert.deepEqual(JSON.parse(result.stdout), expected);
  assert.equal(result.stdout, JSON.stringify(expected) + '\n');
}
function failure(args) {
  const result = cli(args);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.ok(result.stderr.trim());
}

test('all drift categories, ordering, exact bytes and immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'Z', 'é', 'a space\t\n', 'both', 'mode', 'size', 'gone/x', 'link/x', 'block/x', 'directory', 'dangling'];
  for (const name of names) put(root, name, Buffer.from([0, 255, 10]));
  const paths = Object.freeze([...names]);
  const manifest = createManifest(root, paths);
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  manifest.files.reverse();
  for (const entry of manifest.files) {
    if (entry.path === 'size') entry.size++;
    Object.freeze(entry);
  }
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  const before = JSON.stringify(manifest);
  fs.writeFileSync(path.join(root, 'both'), 'different');
  fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.rmSync(path.join(root, 'gone'), { recursive:true });
  fs.rmSync(path.join(root, 'link'), { recursive:true });
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'block'), { recursive:true });
  put(root, 'block');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  fs.unlinkSync(path.join(root, 'dangling'));
  fs.symlinkSync('absent', path.join(root, 'dangling'));
  put(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false,
    unchanged:['z', 'Z', 'é', 'a space\t\n'].sort(),
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'mode', reasons:['mode']}, {path:'size', reasons:['content']}],
    missing:['gone/x'], unsafe:['block/x', 'dangling', 'directory', 'link/x']
  });
  assert.equal(JSON.stringify(manifest), before);
  for (const name of ['block/x', 'dangling', 'directory', 'link/x', 'gone/x']) {
    assert.throws(() => createManifest(root, [name]), Error);
  }
});

test('complete manifest validation and safe integer boundary', t => {
  const root = fixture(t);
  put(root, 'a');
  const entry = createManifest(root, ['a']).files[0];
  for (const size of [0, Number.MAX_SAFE_INTEGER]) {
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, size}]}).changed,
      [{path:'a', reasons:['content']}]);
  }
  const badEntries = [null, [], 3, {},
    ...[-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '3', undefined].map(size => ({...entry, size})),
    ...[-1, 512, 1.5, NaN, '416', undefined].map(mode => ({...entry, mode})),
    ...['a'.repeat(64) + '\n', 'A'.repeat(64), 'g'.repeat(64), 'a'.repeat(63), 42, undefined].map(sha256 => ({...entry, sha256})),
    ...['', '/a', 'a\\b', 'a\0b', 'a//b', 'a/', '.', '..', 'a/./b', 'a/../b', 1, undefined].map(p => ({...entry, path:p}))];
  for (const invalid of badEntries) {
    assert.throws(() => verifyManifest(root, {version:1, files:[entry, invalid]}), Error);
  }
  for (const invalid of [null, [], 1, {}, {version:2, files:[]}, {version:1, files:{}}, {version:1, files:[entry, {...entry}]}]) {
    assert.throws(() => verifyManifest(root, invalid), Error);
  }
  const empty = {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]};
  assert.deepEqual(verifyManifest(root, {version:1, files:[], extra:true}), empty);
  assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, extra:true}]}).unchanged, ['a']);
  assert.throws(() => createManifest(root, ['a', 'a']), Error);
  assert.throws(() => createManifest(root, 'a'), Error);
  for (const p of ['', '/a', 'a\\b', 'a\0b', 'a//b', 'a/', '.', '..']) {
    assert.throws(() => createManifest(root, [p]), Error);
  }
});

test('roots must exist and must not be symlinks, including trailing slash', t => {
  const root = fixture(t);
  put(root, 'file');
  fs.symlinkSync(root, path.join(root, 'alias'));
  for (const invalid of ['', path.join(root, 'absent'), path.join(root, 'file'), path.join(root, 'alias'), path.join(root, 'alias') + '/']) {
    assert.throws(() => createManifest(invalid, []), Error);
    assert.throws(() => verifyManifest(invalid, {version:1, files:[]}), Error);
  }
  assert.deepEqual(createManifest(root + '/', []), {version:1, files:[]});
});

test('CLI output, statuses, failures and import isolation', t => {
  const root = fixture(t);
  put(root, 'a\t\n é');
  const manifest = createManifest(root, ['a\t\n é']);
  const input = path.join(root, 'manifest.json');
  fs.writeFileSync(input, JSON.stringify(manifest));
  success(['create', root, 'a\t\n é'], 0, manifest);
  success(['create', root], 0, {version:1, files:[]});
  success(['verify', root, input], 0, verifyManifest(root, manifest));
  fs.writeFileSync(path.join(root, 'a\t\n é'), 'xyz');
  success(['verify', root, input], 1, verifyManifest(root, manifest));
  for (const args of [[], ['create'], ['verify'], ['verify', root], ['verify', root, input, 'extra'], ['nope', root],
    ['create', root, '../x'], ['create', root, 'missing'], ['create', root, 'a\t\n é', 'a\t\n é'],
    ['create', path.join(root, 'missing')], ['verify', root, path.join(root, 'missing')], ['verify', root, root],
    ['verify', path.join(root, 'missing'), input]]) failure(args);
  for (const value of ['{', 'null', '{"version":2,"files":[]}', '{"version":1,"files":[{}]}']) {
    fs.writeFileSync(input, value);
    failure(['verify', root, input]);
  }
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.ifError(imported.error);
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

