+    if (seen.has(entry.path)) throw Error('duplicate manifest path');
+    seen.add(entry.path);
+    if (typeof entry.sha256 !== 'string' || entry.sha256.length !== 64 || !/^[0-9a-f]{64}$/.test(entry.sha256)
+      || !Number.isSafeInteger(entry.size) || entry.size < 0
+      || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid manifest metadata');
+  }
